* { box-sizing: border-box; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #243532;
  background: #f3eee4;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #fffaf0, #f3eee4 70%);
}

.card {
  width: min(100%, 480px);
  padding: clamp(24px, 6vw, 40px);
  border: 1px solid #e2dbcd;
  border-radius: 24px;
  background: #fffdf8;
  box-shadow: 0 18px 50px #354c4214, 0 2px 7px #354c420d;
}

.heading { text-align: center; }
.eyebrow, .status-label {
  margin: 0;
  color: #6f827a;
  font-size: 0.75rem;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
h1 { margin: 8px 0 6px; font-size: clamp(2rem, 8vw, 2.5rem); line-height: 1.1; letter-spacing: -0.04em; }
.intro { margin: 0 auto; max-width: 330px; color: #61716b; line-height: 1.55; }
.game { width: min(100%, 340px); margin: 28px auto 0; }
.board {
  --gap: 5px;
  position: relative;
  display: grid;
  width: 100%;
  aspect-ratio: 1;
  grid-template-columns: repeat(5, 1fr);
  grid-template-rows: repeat(5, 1fr);
  gap: var(--gap);
  padding: 8px;
  overflow: hidden;
  border: 1px solid #d8e0d8;
  border-radius: 18px;
  background-color: #e9f0e9;
  background-image: linear-gradient(#d4e0d6 1px, transparent 1px), linear-gradient(90deg, #d4e0d6 1px, transparent 1px);
  background-size: calc((100% - 16px - var(--gap) * 4) / 5 + var(--gap)) calc((100% - 16px - var(--gap) * 4) / 5 + var(--gap));
  background-position: 8px 8px;
}
.robot {
  position: absolute;
  z-index: 1;
  top: 8px;
  left: 8px;
  width: calc((100% - 16px - var(--gap) * 4) / 5);
  height: calc((100% - 16px - var(--gap) * 4) / 5);
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #d8794d;
  box-shadow: 0 3px 8px #94462638;
  transition: transform 180ms cubic-bezier(.2,.75,.25,1);
}
.robot span {
  width: 38%;
  height: 38%;
  display: block;
  border-radius: 4px;
  background: #fffaf0;
  clip-path: polygon(0 0, 100% 50%, 0 100%);
  transform: rotate(0deg);
  transition: transform 180ms ease;
}
.status { margin: 22px 0 16px; text-align: center; }
.status-label { font-size: 0.68rem; }
.status p { margin: 5px 0 0; font-size: 1rem; font-weight: 650; }
.controls { display: grid; grid-template-columns: 1fr 1.15fr 1fr; gap: 8px; }
button {
  min-height: 52px;
  padding: 10px 8px;
  border: 1px solid #d8e0d8;
  border-radius: 12px;
  background: #f5f7f1;
  color: #30443d;
  font: inherit;
  font-weight: 650;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, transform 100ms ease, box-shadow 120ms ease;
}
button span { font-size: 0.9rem; }
button:hover { border-color: #9eafa2; background: #eaf0e8; }
button:active { transform: translateY(1px) scale(0.98); }
button:focus-visible { outline: 3px solid #d8794d; outline-offset: 3px; }
button.primary { border-color: #355b4e; background: #355b4e; color: #fffdf8; }
button.primary:hover { border-color: #27483d; background: #27483d; }
.reset { width: 100%; min-height: 46px; margin-top: 10px; border-color: transparent; background: transparent; color: #61716b; }
.reset:hover { border-color: #e2dbcd; background: #f7f3ea; color: #30443d; }
footer { margin-top: 22px; color: #87928b; text-align: center; font-size: 0.85rem; }

@media (max-width: 400px) {
  body { padding: 16px 12px; }
  .card { padding: 24px 18px; }
  .game { margin-top: 22px; }
  button { padding-inline: 5px; }
  button span { font-size: 0.82rem; }
}

const board = document.getElementById('board');
const robot = document.getElementById('robot');
const status = document.getElementById('status');
const directionNames = ['right', 'down', 'left', 'up'];
const cellSize = () => (board.clientWidth - 16 - 20) / 5 + 5;

let row = 0;
let column = 0;
let direction = 0;

function render() {
  const step = cellSize();
  robot.style.transform = `translate(${column * step}px, ${row * step}px)`;
  robot.firstElementChild.style.transform = `rotate(${direction * 90}deg)`;
  status.innerHTML = `Row ${row + 1}, Column ${column + 1} <span aria-hidden="true">·</span> Facing ${directionNames[direction]}`;
  board.setAttribute('aria-label', `5 by 5 grid. Robot at row ${row + 1}, column ${column + 1}, facing ${directionNames[direction]}.`);
}

document.getElementById('forward').addEventListener('click', () => {
  if (direction === 0 && column < 4) column++;
  else if (direction === 1 && row < 4) row++;
  else if (direction === 2 && column > 0) column--;
  else if (direction === 3 && row > 0) row--;
  render();
});

document.getElementById('left').addEventListener('click', () => {
  direction = (direction + 3) % 4;
  render();
});

document.getElementById('right').addEventListener('click', () => {
  direction = (direction + 1) % 4;
  render();
});

document.getElementById('reset').addEventListener('click', () => {
  row = 0;
  column = 0;
  direction = 0;
  render();
});

window.addEventListener('resize', render);
render();
